use std::path::PathBuf;
use std::process::Command;

use super::{IMAGE_BASE, PROVISION, VmSpec, lima_yaml};
use crate::facts::Os;

fn spec() -> VmSpec {
  VmSpec {
    cpus: 10,
    memory_gib: 16,
    disk_gib: 100,
    base: IMAGE_BASE.to_owned(),
    mounts: vec![
      PathBuf::from("/Users/dev/work tree"),
      PathBuf::from("/Users/dev/main/.git"),
    ],
  }
}

#[test]
fn the_macos_file_uses_vz_virtiofs_and_only_the_planned_mounts() {
  assert_eq!(
    lima_yaml(&spec(), Os::Macos, "8.5.0"),
    "# Generated by toolu sandbox 8.5.0; change it with `toolu config set sandbox.<key>`.
minimumLimaVersion: \"2.0.0\"
base:
- \"template:_images/debian-13\"
vmType: \"vz\"
mountType: \"virtiofs\"
containerd:
  system: false
  user: false
cpus: 10
memory: \"16GiB\"
disk: \"100GiB\"
mounts:
- location: \"/Users/dev/work tree\"
  writable: true
- location: \"/Users/dev/main/.git\"
  writable: true
"
  );
}

#[test]
fn elsewhere_lima_picks_the_vm_type_and_quotes_survive() {
  let mut odd = spec();
  odd.mounts = vec![PathBuf::from("/srv/it's \"x\"")];
  let text = lima_yaml(&odd, Os::Linux, "8.5.0");
  assert!(
    !text.contains("vmType") && !text.contains("mountType"),
    "{text}"
  );
  assert!(
    text.contains("- location: \"/srv/it's \\\"x\\\"\"\n"),
    "{text}"
  );
}

#[test]
fn the_provisioning_script_is_valid_bash_and_pins_the_gate_tools() {
  let status = Command::new("bash")
    .args(["-n", "-c", PROVISION])
    .status()
    .unwrap();
  assert!(status.success());
  for pin in [
    "cargo-deny@0.20.2",
    "cargo-machete@0.9.2",
    "cargo-llvm-cov@0.9.1",
    "cargo-nextest@0.9.146",
    "@ast-grep/cli@0.50.0",
    "bubblewrap",
    "rustup toolchain install",
  ] {
    assert!(PROVISION.contains(pin), "{pin}");
  }
}

#[test]
fn the_pins_match_the_release_workflow() {
  let root = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");
  let workflow =
    std::fs::read_to_string(format!("{root}/.github/workflows/release-native.yml")).unwrap();
  let line = |marker: &str| {
    workflow
      .split_once(marker)
      .unwrap()
      .1
      .lines()
      .next()
      .unwrap()
  };
  let pins: Vec<&str> = line("tool: ")
    .split(',')
    .chain([line("npm install -g ")])
    .map(str::trim)
    .collect();
  assert_eq!(pins.len(), 5, "{pins:?}");
  // The tests run jq and gh for real, and npm's update notifier stalls jscpd.
  for pin in pins.into_iter().chain([" jq gh ", "update-notifier false"]) {
    assert!(PROVISION.contains(pin), "the provisioning lacks {pin}");
  }
}
